import React, { useState, useEffect, useCallback } from 'react';
import './CSS/SellerDashboard.css';
import { Link } from 'react-router-dom';
import axios from 'axios';

const API_BASE_URL = 'http://localhost:4000/api/seller';

const SellerDashboard = () => {
  const [activeTab, setActiveTab] = useState('inventory');
  const [products, setProducts] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All');

  // Modals
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState(null);

  // Form state
  const [newProduct, setNewProduct] = useState({
    title: '',
    price: '',
    category: 'Electronics',
    stock: '',
    description: '',
    imageUrl: '',
  });

  // READ: Fetch product inventory
  const fetchProducts = useCallback(async () => {
    try {
      const res = await axios.get(`${API_BASE_URL}/products`);
      if (res.data.success) {
        setProducts(res.data.products);
      }
    } catch (err) {
      console.error('Error fetching products:', err);
    }
  }, []);

  useEffect(() => {
    fetchProducts();
  }, [fetchProducts]);

  // CREATE: Submit new product
  const handleAddProductSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post(`${API_BASE_URL}/products`, newProduct);
      if (res.data.success) {
        alert('Product added successfully!');
        setIsAddModalOpen(false);
        setNewProduct({ title: '', price: '', category: 'Electronics', stock: '', description: '', imageUrl: '' });
        fetchProducts();
      }
    } catch (err) {
      alert(err.response?.data?.message || 'Failed to add product');
    }
  };

  // UPDATE: Edit existing product
  const handleUpdateProductSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.put(`${API_BASE_URL}/products/${editingProduct._id}`, editingProduct);
      if (res.data.success) {
        alert('Product updated successfully!');
        setEditingProduct(null);
        fetchProducts();
      }
    } catch (err) {
      alert(err.response?.data?.message || 'Failed to update product');
    }
  };

  // DELETE: Remove product
  const handleDeleteProduct = async (id) => {
    if (window.confirm('Are you sure you want to delete this product listing?')) {
      try {
        const res = await axios.delete(`${API_BASE_URL}/products/${id}`);
        if (res.data.success) {
          fetchProducts();
        }
      } catch (err) {
        alert(err.response?.data?.message || 'Failed to delete product');
      }
    }
  };

  // Filter products by search and category
  const filteredProducts = products.filter((item) => {
    const matchesSearch = item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          item._id.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = categoryFilter === 'All' || item.category === categoryFilter;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="admin-wrapper">
      <aside className="admin-sidebar">
        <div className="sidebar-brand">
          <h2>HEX<span>STORE</span></h2>
          <span className="brand-subtitle">Seller Portal</span>
        </div>
        <nav className="sidebar-nav">
          <button className={activeTab === 'inventory' ? 'active' : ''} onClick={() => setActiveTab('inventory')}>
            Inventory & Products
          </button>
        </nav>
      </aside>

      <div className="admin-main">
        <header className="admin-header">
          <div className="header-search">
            <input
              type="text"
              placeholder="Search products by title or ID..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="header-right">
            <Link to="/" className="btn-storefront">View Storefront</Link>
          </div>
        </header>

        <main className="admin-body">
          {activeTab === 'inventory' && (
            <div className="tab-panel fade-in">
              <div className="split-main-card full-width">
                <div className="card-header-flex">
                  <div>
                    <h3>Product Inventory</h3>
                    <p className="card-subtitle">Manage price listings, update available stock, and add items</p>
                  </div>
                  <div style={{ display: 'flex', gap: '12px' }}>
                    <select className="category-filter-select" value={categoryFilter} onChange={(e) => setCategoryFilter(e.target.value)}>
                      <option value="All">All Categories</option>
                      <option value="Electronics">Electronics</option>
                      <option value="Accessories">Accessories</option>
                      <option value="Apparel">Apparel</option>
                      <option value="Home">Home</option>
                    </select>
                    <button className="btn-primary" onClick={() => setIsAddModalOpen(true)}>+ Add New Product</button>
                  </div>
                </div>

                <div className="table-responsive">
                  <table className="enhanced-table">
                    <thead>
                      <tr>
                        <th>Product Info</th>
                        <th>Category</th>
                        <th>Price</th>
                        <th>Stock</th>
                        <th>Status</th>
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {filteredProducts.map((product) => (
                        <tr key={product._id}>
                          <td>
                            <div className="user-cell">
                              <div className="store-avatar-box">
                                {product.imageUrl ? (
                                  <img src={product.imageUrl} alt={product.title} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                ) : (
                                  product.title.charAt(0)
                                )}
                              </div>
                              <div>
                                <strong className="user-name">{product.title}</strong>
                                <span className="user-subtext">ID: {product._id}</span>
                              </div>
                            </div>
                          </td>
                          <td>{product.category}</td>
                          <td><strong className="text-dark">${product.price.toFixed(2)}</strong></td>
                          <td>{product.stock} units</td>
                          <td>
                            <span className={`badge-pill status-${product.stock > 0 ? 'active' : 'blocked'}`}>
                              {product.stock > 0 ? 'In Stock' : 'Out of Stock'}
                            </span>
                          </td>
                          <td>
                            <div style={{ display: 'flex', gap: '8px' }}>
                              <button className="btn-table-action" onClick={() => setEditingProduct({ ...product })}>Edit</button>
                              <button className="btn-control-toggle danger" onClick={() => handleDeleteProduct(product._id)}>Delete</button>
                            </div>
                          </td>
                        </tr>
                      ))}
                      {filteredProducts.length === 0 && (
                        <tr><td colSpan="6" style={{ textAlign: 'center', padding: '24px' }}>No products found.</td></tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </main>
      </div>

      {/* Add Modal */}
      {isAddModalOpen && (
        <div className="modal-backdrop" onClick={() => setIsAddModalOpen(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>Add New Product</h3>
              <button className="btn-modal-close" onClick={() => setIsAddModalOpen(false)}>&times;</button>
            </div>
            <form onSubmit={handleAddProductSubmit} className="settings-form" style={{ marginTop: '16px' }}>
              <div className="setting-field">
                <label>Title *</label>
                <input type="text" required value={newProduct.title} onChange={(e) => setNewProduct({ ...newProduct, title: e.target.value })} />
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
                <div className="setting-field">
                  <label>Price ($) *</label>
                  <input type="number" step="0.01" required value={newProduct.price} onChange={(e) => setNewProduct({ ...newProduct, price: e.target.value })} />
                </div>
                <div className="setting-field">
                  <label>Stock *</label>
                  <input type="number" required value={newProduct.stock} onChange={(e) => setNewProduct({ ...newProduct, stock: e.target.value })} />
                </div>
              </div>
              <div className="setting-field">
                <label>Category</label>
                <select value={newProduct.category} onChange={(e) => setNewProduct({ ...newProduct, category: e.target.value })}>
                  <option value="Electronics">Electronics</option>
                  <option value="Accessories">Accessories</option>
                  <option value="Apparel">Apparel</option>
                  <option value="Home">Home</option>
                </select>
              </div>
              <div className="setting-field">
                <label>Image URL</label>
                <input type="url" value={newProduct.imageUrl} onChange={(e) => setNewProduct({ ...newProduct, imageUrl: e.target.value })} />
              </div>
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '20px' }}>
                <button type="button" className="btn-outline-sm" onClick={() => setIsAddModalOpen(false)}>Cancel</button>
                <button type="submit" className="btn-primary">Publish</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Edit Modal */}
      {editingProduct && (
        <div className="modal-backdrop" onClick={() => setEditingProduct(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>Update Product</h3>
              <button className="btn-modal-close" onClick={() => setEditingProduct(null)}>&times;</button>
            </div>
            <form onSubmit={handleUpdateProductSubmit} className="settings-form" style={{ marginTop: '16px' }}>
              <div className="setting-field">
                <label>Title</label>
                <input type="text" value={editingProduct.title} onChange={(e) => setEditingProduct({ ...editingProduct, title: e.target.value })} />
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
                <div className="setting-field">
                  <label>Price ($)</label>
                  <input type="number" step="0.01" value={editingProduct.price} onChange={(e) => setEditingProduct({ ...editingProduct, price: e.target.value })} />
                </div>
                <div className="setting-field">
                  <label>Stock</label>
                  <input type="number" value={editingProduct.stock} onChange={(e) => setEditingProduct({ ...editingProduct, stock: e.target.value })} />
                </div>
              </div>
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '20px' }}>
                <button type="button" className="btn-outline-sm" onClick={() => setEditingProduct(null)}>Cancel</button>
                <button type="submit" className="btn-primary">Save Changes</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SellerDashboard;
